import{_ as o,o as a,c as d,a2 as c}from"./chunks/framework.BDCokyix.js";const b=JSON.parse('{"title":"5. Building Block View","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/arc42/05-building-block-view.md","filePath":"architecture/arc42/05-building-block-view.md","lastUpdated":1780254295000}'),i={name:"architecture/arc42/05-building-block-view.md"};function r(s,e,t,n,l,m){return a(),d("div",null,[...e[0]||(e[0]=[c('<h1 id="_5-building-block-view" tabindex="-1">5. Building Block View <a class="header-anchor" href="#_5-building-block-view" aria-label="Permalink to &quot;5. Building Block View&quot;">​</a></h1><p>This section lists the major building blocks in the repo and how they relate.</p><h2 id="level-1-system-decomposition" tabindex="-1">Level 1: System decomposition <a class="header-anchor" href="#level-1-system-decomposition" aria-label="Permalink to &quot;Level 1: System decomposition&quot;">​</a></h2><ul><li><strong>Desktop app</strong> (<code>desktop/</code>) <ul><li><code>desktop/soma</code>: the only Electron app. The typing companion (Tapia) is delivered as the <code>/practice</code> route inside this app.</li></ul></li><li><strong>Backend workspace</strong> (<code>backend/</code>) <ul><li><code>backend/bins/somad</code>: the only standalone backend binary (subcommands for bot / relay / rendezvous / bff / all-composed mode).</li><li><code>backend/crates/daemon</code> and <code>backend/crates/agentd</code>: <strong>library crates</strong> (no binary) hosting the desktop peer + agent runtimes; linked into <code>backend/crates/soma-node</code>.</li><li>Shared crates under <code>backend/crates/*</code> (peer runtime, storage, networking, metrics, …).</li></ul></li><li><strong>Protocols</strong> (<code>proto/</code>): protobuf service and message definitions.</li><li><strong>Deployment</strong> (<code>deploy/</code>, <code>compose/</code>, <code>Dockerfile</code>): helm charts, compose bundles, container images for <code>somad</code>.</li></ul><h2 id="level-2-backend-artifacts" tabindex="-1">Level 2: Backend artifacts <a class="header-anchor" href="#level-2-backend-artifacts" aria-label="Permalink to &quot;Level 2: Backend artifacts&quot;">​</a></h2><h3 id="server-binary" tabindex="-1">Server binary <a class="header-anchor" href="#server-binary" aria-label="Permalink to &quot;Server binary&quot;">​</a></h3><ul><li><code>backend/bins/somad</code> (<code>somad</code>) <ul><li>Single binary with <code>bot</code> / <code>relay</code> / <code>rendezvous</code> / <code>bff</code> / <code>all</code> subcommands. Replaces the former per-service <code>soma-botd</code>, <code>soma-relayd</code>, <code>soma-rendezvousd</code>, <code>soma-bffd</code>, <code>soma-serverd</code> binaries.</li><li><code>bot</code> mode: libp2p peer with cache-only blob behaviour (VDF role) + Axum HTTP surface for info/health/metrics; optional admin control plane in <code>admin</code> mode.</li><li><code>relay</code> mode: libp2p Circuit Relay v2 server + Axum health/metrics.</li><li><code>rendezvous</code> mode: libp2p Rendezvous server + Axum health/metrics.</li><li><code>bff</code> mode: Axum business API for LLM-facing features.</li><li><code>all</code> mode: TOML-composed multi-mode runner.</li></ul></li></ul><h3 id="desktop-runtime-in-process-via-napi" tabindex="-1">Desktop runtime (in-process via napi) <a class="header-anchor" href="#desktop-runtime-in-process-via-napi" aria-label="Permalink to &quot;Desktop runtime (in-process via napi)&quot;">​</a></h3><ul><li><code>backend/crates/soma-node</code> (<code>@soma/node</code>): napi-rs cdylib loaded by the Electron main process. Embeds the daemon + agent libraries; exposes one <code>SomaHandle</code> to JS.</li><li><code>backend/crates/daemon</code> (<code>soma-daemon</code>, library only): libp2p peer identity, blob store, repositories, event bus. In-process <code>DaemonHandle</code> facade for the napi addon.</li><li><code>backend/crates/agentd</code> (<code>soma-agentd</code>, library only): Yjs drift resolver and agent runtime. In-process <code>AgentHandle</code> facade for the napi addon.</li></ul><h2 id="level-3-key-shared-crates" tabindex="-1">Level 3: Key shared crates <a class="header-anchor" href="#level-3-key-shared-crates" aria-label="Permalink to &quot;Level 3: Key shared crates&quot;">​</a></h2><ul><li><code>backend/crates/peer</code> (<code>soma-peer</code>): libp2p behaviour wiring, protocol IDs, peer command/event loop.</li><li><code>backend/crates/net</code> (<code>soma-net</code>): transport and identity helpers (e.g., default identity path).</li><li><code>backend/crates/membership</code> (<code>soma-membership</code>): join deciders, policies, capability flows.</li><li><code>backend/crates/storage</code> (<code>soma-storage</code>): SQL repositories and migrations.</li><li><code>backend/crates/vdfs</code> (<code>soma-vdfs</code>): blob provider boundary and CAS helpers (name kept for historical reasons).</li><li><code>backend/crates/metrics</code> (<code>soma-metrics</code>): Prometheus metrics router helpers.</li><li><code>backend/crates/proto-build</code> (<code>soma-proto-build</code>): compile-time prost/tonic bindings for <code>proto/</code> (used for record types; the desktop side no longer uses any tonic service stubs).</li></ul>',11)])])}const u=o(i,[["render",r]]);export{b as __pageData,u as default};
